/**
 * BFF 1:1 mock payloads for Innovation Hub Performance & Breakdown.
 * Future view ids: overtime, contribution-waterfall, deep-dive-waterfall.
 */
import { PerformanceAndBreakdownOvertimeMock } from './LineBarChart/overtime';
import { PerformanceAndBreakdownDeepDiveMockByViewBy } from './Waterfall';
import { PerformanceAndBreakdownContributionWaterfallMock } from './Waterfall/contribution';

export const PERFORMANCE_AND_BREAKDOWN_MOCK = {
  overtime: PerformanceAndBreakdownOvertimeMock,
  contribution: PerformanceAndBreakdownContributionWaterfallMock,
  deepDive: PerformanceAndBreakdownDeepDiveMockByViewBy,
} as const;

export { PerformanceAndBreakdownOvertimeMock } from './LineBarChart/overtime';
export { PerformanceAndBreakdownContributionWaterfallMock } from './Waterfall/contribution';
export { PerformanceAndBreakdownDeepDiveMockByViewBy } from './Waterfall';
export {
  PerformanceAndBreakdownDeepDiveEntityComparisonLines,
  PerformanceAndBreakdownDeepDiveSkuComparisonLines,
} from './Waterfall/deepDiveComparisonLines';
